<?php
require_once 'config.php';
$errors=[];$first_name=$middle_name=$last_name=$email=$birthday=$sex=$student_number=$program=$enrolment_date='';
if($_SERVER['REQUEST_METHOD']==='POST'){
$first_name=trim($_POST['first_name']??'');$middle_name=trim($_POST['middle_name']??'');$last_name=trim($_POST['last_name']??'');$email=trim($_POST['email']??'');$birthday=trim($_POST['birthday']??'');$sex=trim($_POST['sex']??'');$student_number=trim($_POST['student_number']??'');$program=trim($_POST['program']??'');$enrolment_date=trim($_POST['enrolment_date']??'');
if($first_name===''||strlen($first_name)<2||strlen($first_name)>100||!preg_match('/^[A-Za-z\s]+$/',$first_name))$errors['first_name']='First name is required, 2-100 characters, letters and spaces only.';
if($last_name===''||strlen($last_name)<2||strlen($last_name)>100||!preg_match('/^[A-Za-z\s]+$/',$last_name))$errors['last_name']='Last name is required, 2-100 characters, letters and spaces only.';
if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors['email']='Enter a valid email address.';
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$birthday))$errors['birthday']='Birthday must use YYYY-MM-DD.';
if(!in_array($sex,['Male','Female'],true))$errors['sex']='Sex must be Male or Female.';
if($student_number!==''&&(strlen($student_number)>50||!preg_match('/^[A-Za-z0-9]+$/',$student_number)))$errors['student_number']='Student number must be alphanumeric and max 50 characters.';
if($program!==''&&strlen($program)>200)$errors['program']='Program must be at most 200 characters.';
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$enrolment_date))$errors['enrolment_date']='Enrolment date must use YYYY-MM-DD.';
if(empty($errors)){ $stmt=$pdo->prepare('INSERT INTO students(id,first_name,middle_name,last_name,birthday,sex,email,student_number,program,enrolment_date) VALUES(UUID(),?,?,?,?,?,?,?,?,?)');$stmt->execute([$first_name,$middle_name,$last_name,$birthday,$sex,$email,$student_number,$program,$enrolment_date]); echo '<p class="success">Student created successfully!</p>'; }
}
?>
<!doctype html><html><head><title>Create Student</title><link rel="stylesheet" href="style.css"></head><body><div class="container"><a href="index.php">Back</a><h2>Add New Student</h2><form method="POST"><label>First Name<input name="first_name" value="<?=htmlspecialchars($first_name)?>"><?php if(isset($errors['first_name'])):?><span class="error"><?=htmlspecialchars($errors['first_name'])?></span><?php endif;?></label><label>Middle Name<input name="middle_name" value="<?=htmlspecialchars($middle_name)?>"></label><label>Last Name<input name="last_name" value="<?=htmlspecialchars($last_name)?>"><?php if(isset($errors['last_name'])):?><span class="error"><?=htmlspecialchars($errors['last_name'])?></span><?php endif;?></label><label>Birthday<input type="date" name="birthday" value="<?=htmlspecialchars($birthday)?>"><?php if(isset($errors['birthday'])):?><span class="error"><?=htmlspecialchars($errors['birthday'])?></span><?php endif;?></label><label>Sex<select name="sex"><option value="">Select</option><option value="Male" <?=$sex==='Male'?'selected':''?>>Male</option><option value="Female" <?=$sex==='Female'?'selected':''?>>Female</option></select><?php if(isset($errors['sex'])):?><span class="error"><?=htmlspecialchars($errors['sex'])?></span><?php endif;?></label><label>Email<input type="email" name="email" value="<?=htmlspecialchars($email)?>"><?php if(isset($errors['email'])):?><span class="error"><?=htmlspecialchars($errors['email'])?></span><?php endif;?></label><label>Student Number<input name="student_number" value="<?=htmlspecialchars($student_number)?>"><?php if(isset($errors['student_number'])):?><span class="error"><?=htmlspecialchars($errors['student_number'])?></span><?php endif;?></label><label>Program<input name="program" value="<?=htmlspecialchars($program)?>"><?php if(isset($errors['program'])):?><span class="error"><?=htmlspecialchars($errors['program'])?></span><?php endif;?></label><label>Enrolment Date<input type="date" name="enrolment_date" value="<?=htmlspecialchars($enrolment_date)?>"><?php if(isset($errors['enrolment_date'])):?><span class="error"><?=htmlspecialchars($errors['enrolment_date'])?></span><?php endif;?></label><button class="btn">Create Student</button></form></div></body></html>